function bossFullyVisible(e){const scale=currentLayout().actors.boss,z=zoom??1,extent=worldThemes[previewStage]?175:104,head=worldThemes[previewStage]?210:145,left=center.x+(e.x-extent*scale-center.x)*z,right=center.x+(e.x+extent*scale-center.x)*z,top=center.y+(e.y-head*scale-center.y)*z,bottom=center.y+(e.y+12*scale-center.y)*z;return left>=10&&right<=W-10&&top>=10&&bottom<=H*(1-.132)-8;}
