function render(){if(dragCanvas.width!==canvas.width||dragCanvas.height!==canvas.height){dragCanvas.width=canvas.width;dragCanvas.height=canvas.height;}dragContext.setTransform(1,0,0,1,0,0);dragContext.clearRect(0,0,dragCanvas.width,dragCanvas.height);renderHeldVisual();g.setTransform(ratio,0,0,ratio,0,0);g.clearRect(0,0,W,H);g.fillStyle=['dune','oasis','noon'].includes(previewStage)?'#e9b478':previewStage==='moon'||previewStage==='camp'?'#476461':'#859f50';g.fillRect(0,0,W,H);g.save();if(scene==='battle'){g.translate(center.x,center.y);g.scale(zoom,zoom);g.translate(-center.x,-center.y);}const focus=introWeight();if(focus){const boss=bossIntro.boss,z=1+focus*.75;g.translate(W/2+W*.06*focus,H*.49);g.scale(z,z);g.translate(-(W/2+(boss.x-W/2)*focus),-(H*.49+(boss.y-65-H*.49)*focus));}drawStageBackground();if(scene==='plants'){g.restore();return;}if(scene==='home'){drawGroundLight(345,315,1.08);drawGrid(345,315,1.08);g.restore();return;}drawGroundLight(center.x,center.y);drawBossTrails();drawGrid(center.x,center.y);drawSelection();for(const e of effects){if(e.kind==='merge')drawLevelBeam(e);else if(e.kind==='plant-death')drawPlantDeath(e);}const actors=[...units.filter(u=>u!==drag?.unit).map(u=>({kind:'plant',u,y:position(u.slot).y})),...enemies.filter(e=>e!==bossIntro?.boss).map(e=>({kind:'enemy',e,y:e.y}))].sort((a,b)=>a.y-b.y);for(const actor of actors){if(actor.kind==='plant'){const u=actor.u,p=visualPosition(u),bob=paused?0:Math.sin(time*2+u.slot)*.8;const bounce=u.age<.28?Math.sin(u.age/.28*Math.PI):0;sprite(names[u.type],p.x,p.y+22+bob,(67+Math.min(4,u.level-1)*1.5)*(1+(reducedMotion()?0:Math.sin((1-(u.levelUp||0)/.85)*Math.PI)*.15)),{flip:u.flip,bounce,phase:u.id*.73,star:u.level,hit:(u.hit||0)/.26,recoil:Math.sin(u.recoil/.16*Math.PI)*2});drawAllyHealth(u,p);}else{const e=actor.e,size=e.kind==='boss'?150:e.kind==='bruiser'?85:e.kind==='courier'?60:57;if(e.kind==='boss')drawBoss(e,size);else sprite(e.artId||e.kind,e.x,e.y+8+Math.sin(time*5+e.phase)*1.8,size,{flip:e.flip,phase:e.phase,hit:e.hit/.26,recoil:Math.sin(e.recoil/.2*Math.PI)*3,action:e.moving?'walk':e.recoil>0?'attack':'idle'});if(e.hp<e.maxHp)bar(e.x,e.y-size-4,e.hp/e.maxHp,e.kind==='bruiser'?58:36);}}
for(const shot of shots){drawShotTail(shot);const angle=shot.heading??Math.atan2(shot.ty-shot.y,shot.tx-shot.x);g.save();g.translate(shot.x,shot.y);g.rotate(angle);g.lineJoin='round';g.lineWidth=2;g.strokeStyle='#172725';if(shot.enemy){g.fillStyle='#b27ce9';g.beginPath();g.moveTo(10,0);g.lineTo(-3,-6);g.lineTo(-8,0);g.lineTo(-3,6);g.closePath();g.fill();g.stroke();ellipse(-9,0,5,2,'#c6a3f46a');}else if(shot.type===0||shot.type===3){ellipse(-10,0,12,2,'#d5fc5599');ellipse(0,0,6,4,shot.type===3?'#ffd845':'#b8ef41');g.stroke();ellipse(2,-1,2,1,'#fff8c7');}else if(shot.type===1){g.strokeStyle='#f8e1a3';g.lineWidth=4;g.beginPath();g.moveTo(-23,0);g.lineTo(4,0);g.stroke();g.fillStyle='#e6f6c8';g.strokeStyle='#1b382b';g.lineWidth=2;g.beginPath();g.moveTo(13,0);g.lineTo(2,-5);g.lineTo(2,5);g.closePath();g.fill();g.stroke();}else{ellipse(-8,0,12,5,'#ffab3877');ellipse(0,0,9,7,'#ac6831');g.stroke();g.strokeStyle='#ffe19a';g.beginPath();g.moveTo(-4,-4);g.lineTo(4,4);g.moveTo(1,-5);g.lineTo(-3,4);g.stroke();}g.restore();}
for(const effect of effects){const a=effect.life/effect.max;if(effect.kind==='soul'){g.save();g.globalAlpha=Math.min(1,a*2);const h=(effect.size===30?88:47)*(1+(1-a)*.15),x=effect.x+Math.sin((1-a)*8)*7,y=effect.y-(1-a)*85;g.drawImage(combatVfx,120,45,550,800,x-h*.344,y-h*.6,h*.688,h);g.restore();}else if(effect.kind==='enemy-strike'){drawEnemyStrike(effect);}else if(effect.kind==='blast'){g.save();g.globalAlpha=a;g.strokeStyle='#f7bd54';g.lineWidth=3;g.fillStyle='#ed9a2530';g.beginPath();g.arc(effect.x,effect.y,effect.radius*(1-a),0,Math.PI*2);g.fill();g.stroke();g.restore();}else if(effect.kind==='merge'||effect.kind==='plant-death'){continue;}else{g.save();g.globalAlpha=a;label(effect.text,effect.x,effect.y-(1-a)*28,14,effect.enemy?'#dfb3ff':'#fff9d6');g.restore();}}
drawMergeReady();g.restore();if(focus){g.fillStyle=`rgba(10,21,18,${focus*.24})`;g.fillRect(0,0,W,H);const boss=bossIntro.boss,z=1+focus*.75;g.save();g.translate(center.x,center.y);g.scale(zoom,zoom);g.translate(-center.x,-center.y);g.translate(W/2+W*.06*focus,H*.49);g.scale(z,z);g.translate(-(W/2+(boss.x-W/2)*focus),-(H*.49+(boss.y-65-H*.49)*focus));drawBoss(boss,200);g.restore();}}

function drawDesertProps(){paintMapProps(g,currentLayout(),worldArt.props);}
function drawStageBackground(){if(scene==='plants'){drawRawStageBackground();return;}const b=currentLayout().background;g.save();g.translate(600+b.x,300+b.y);g.scale(b.scale,b.scale);g.translate(-600,-300);g.filter='brightness('+b.brightness+')';drawRawStageBackground();g.restore();drawDesertProps();}
function drawRawStageBackground(){if(scene==='plants'){g.fillStyle='#bacd91';g.fillRect(0,0,W,H);g.save();g.globalCompositeOperation='multiply';g.globalAlpha=.14;const factor=W/canvas.getBoundingClientRect().width,clock=window.matchMedia('(prefers-reduced-motion: reduce)').matches?0:performance.now()/75000,dx=(clock%1)*600,dy=(clock%1)*400;g.scale(factor,factor);g.translate(dx,dy);g.fillStyle=g.createPattern(wallpaperTile,'repeat');g.fillRect(-600,-400,W/factor+1200,H/factor+800);g.restore();return;}if(worldArt.grounds[previewStage]){g.save();if(previewStage==='noon')g.filter='brightness(1.1) saturate(.8)';drawExtendedField(worldArt.grounds[previewStage]);g.restore();return;}if(previewStage==='moon'){drawExtendedField(moonField);return;}if(['dune','oasis','noon'].includes(previewStage)){g.save();if(previewStage==='noon')g.filter='brightness('+(1.13*currentLayout().background.brightness)+') saturate(.72)';if(previewStage==='oasis')g.filter='brightness('+currentLayout().background.brightness+') saturate(1.15)';paintSand(g,previewStage,W,H);g.restore();}else{g.save();if(previewStage==='camp'||previewStage==='moon')g.filter=previewStage==='moon'?'brightness(.42) saturate(.42) hue-rotate(30deg)':'brightness('+(.56*currentLayout().background.brightness)+') saturate(.6)';drawExtendedField(scene==='home'?homeField:art.forest.image);g.restore();if(previewStage==='camp'||previewStage==='moon'){g.fillStyle='#273c582e';g.fillRect(0,0,W,H);}}}

function update(dt){time+=dt;if(scene!=='battle'||runResolved)return;sun=Math.min(999,sun+saved.rate*dt);
 if(countdown>0){countdown=Math.max(0,countdown-dt);return;}
 spawnClock-=dt;if(spawned<countForWave(saved,wave)&&spawnClock<=0){enemies.push(freshEnemy(spawned++));spawnClock=spawnInterval(saved,wave);}
 for(const u of units){u.hit=Math.max(0,u.hit-dt);u.recoil=Math.max(0,u.recoil-dt);u.fire-=dt;const p=position(u.slot),target=enemies.filter(e=>e.hp>0&&!(e.kind==='boss'&&!e.introduced)&&Math.hypot(e.x-p.x,e.y-p.y)<ranges[u.type]).sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y))[0];if(target){u.flip=target.x<p.x;if(u.fire<=0){u.fire=rules.troops[u.type].cooldown;u.recoil=.16;const sx=p.x+(u.flip?-22:22),sy=p.y-12;shots.push({x:sx,y:sy,sx,sy,tx:target.x,ty:target.y-16,target,type:u.type,damage:rules.troops[u.type].attack*rules.merge.attackGrowth**(u.level-1),enemy:false});}}}
 for(const e of [...enemies]){e.hit=Math.max(0,e.hit-dt);e.recoil=Math.max(0,e.recoil-dt);e.fire-=dt;const ranged=e.kind==='courier',near=units.map(u=>({u,p:position(u.slot)})).sort((a,b)=>Math.hypot(a.p.x-e.x,a.p.y-e.y)-Math.hypot(b.p.x-e.x,b.p.y-e.y))[0],target=e.kind==='boss'&&!e.introduced?null:near&&(ranged||Math.hypot(near.p.x-e.x,near.p.y-e.y)<140)?near:null,aim=target?.p||center,d=Math.hypot(aim.x-e.x,aim.y-e.y),stop=e.kind==='boss'&&!e.introduced?0:ranged?(e.ruleKind===4?92:180):target?(e.kind==='boss'?58:28):(e.kind==='boss'?85:62);e.flip=aim.x<e.x;e.visualScale=e.kind==='boss'?currentLayout().actors.boss:currentLayout().actors.enemy;e.moving=moveEnemy(e,aim,dt,e.speed,stop,currentObstacles());rememberBossTrail(e,dt);if(e.kind==='boss'&&!e.introduced&&bossFullyVisible(e)&&!bossIntro){startBossIntro(e);break;}if(!e.moving&&d<=stop+3&&e.fire<=0&&!bossIntro){e.fire=ranged?(e.ruleKind===4?2.3:1.8):e.kind==='boss'?1.6:1.2;e.recoil=.2;const damage=(e.kind==='boss'?40:ranged?(e.ruleKind===4?16:10)+wave*2:10)*encounterScale(saved);if(ranged){const sx=e.x+(e.flip?-18:18),sy=e.y-22;shots.push({x:sx,y:sy,sx,sy,tx:aim.x,ty:aim.y-12,enemy:true,targetUnit:target?.u,targetBase:!target,damage});}else{effects.push({kind:'enemy-strike',x:e.x,y:e.y-18,tx:aim.x,ty:aim.y-12,life:.22,max:.22});if(target)hurtPlant(target.u,damage);else hurtBase(damage);}}}
 for(const s of shots){if(s.targetUnit&&!units.includes(s.targetUnit)){s.dead=true;continue;}if(s.target&&!enemies.includes(s.target)){s.dead=true;continue;}rememberTrail(s);const aim=s.target?{x:s.target.x,y:s.target.y-16}:s.targetUnit?position(s.targetUnit.slot):null;if(aim){s.tx=aim.x;s.ty=aim.y;}const dx=s.tx-s.x,dy=s.ty-s.y,d=Math.hypot(dx,dy),step=(s.enemy?220:340)*dt;s.heading=Math.atan2(dy,dx);if(d<=step){s.dead=true;if(s.enemy){if(s.targetUnit)hurtPlant(s.targetUnit,s.damage);else hurtBase(s.damage);}else{hitEnemy(s.target,s.damage);if(s.type===3){effects.push({kind:'blast',x:s.tx,y:s.ty,radius:62,life:.35,max:.35});for(const e of [...enemies])if(e!==s.target&&Math.hypot(e.x-s.tx,e.y-16-s.ty)<62)hitEnemy(e,s.damage*.6);}if(s.type===1){const ax=s.tx-s.sx,ay=s.ty-s.sy,l2=ax*ax+ay*ay;for(const e of [...enemies]){const t=((e.x-s.sx)*ax+(e.y-16-s.sy)*ay)/l2;if(e!==s.target&&t>.25&&t<1.3&&Math.hypot(e.x-s.sx-t*ax,e.y-16-s.sy-t*ay)<18)hitEnemy(e,s.damage*.75);}}}effects.push({kind:'damage',x:s.tx,y:s.ty-20,text:String(Math.round(s.damage)),enemy:s.enemy,life:.65,max:.65});}else{s.x+=dx/d*step;s.y+=dy/d*step;}}
 shots=shots.filter(s=>!s.dead);effects.forEach(e=>{if(e.kind!=='merge')e.life-=dt;});effects=effects.filter(e=>e.life>0);if(baseHp<=0){finish(false);return;}if(spawned>=countForWave(saved,wave)&&!enemies.length){if(wave>=chapter().waves)finish(true);else{wave++;waveKilled=0;spawned=0;spawnClock=1;notify('Wave '+wave);}}
}
function showDialog(title,body,actions){const box=$('#production-dialog');box.innerHTML=`<section><span>${title}</span><h2 id="production-title">${title}</h2><p>${body}</p>${actions.map((a,i)=>`<button data-action="${i}" class="${a.label==='CANCEL'?'secondary':'primary'}" ${a.disabled?'disabled':''}>${a.label}</button>`).join('')}</section>`;box.hidden=false;actions.forEach((a,i)=>box.querySelector(`[data-action="${i}"]`).onclick=a.action);box.querySelector('button:not(:disabled)')?.focus();}
function hideDialog(){$('#production-dialog').hidden=true;}
function timedBonus(title,body,claim,cancel){bonusReady=performance.now()+rules.economy.adDurationMs;showDialog(title,body,[{label:'CONTINUE IN 5',disabled:true,action:()=>{if(!bonusReady||performance.now()<bonusReady)return;bonusReady=0;claim();}}]);const close=document.createElement('button');close.className='bonus-close';close.setAttribute('aria-label','Close bonus');close.textContent='×';close.onclick=()=>{bonusReady=0;cancel();};$('#production-dialog section').append(close);}
function claimDoubleReward(){if(!runReward||runReward.doubled)return false;runReward.doubled=true;saved.coins+=earned;runReward.coins+=earned;save();return true;}
function resultDialog(win,finishedStage,doubled=false){const leave=()=>{hideDialog();paused=false;prepareRewardFlight();showSceneSplash('home');launchRewardFlight();};const actions=[];if(earned>0&&!runReward?.doubled)actions.push({label:'CLAIM ×2',action:()=>timedBonus('BONUS REWARD','Double your coin reward.',()=>{claimDoubleReward();resultDialog(win,finishedStage,true);},()=>resultDialog(win,finishedStage))});actions.push({label:win?'NEXT STAGE':'HOME',action:leave});showDialog(win?'VICTORY!':'TRY AGAIN',`Stage ${finishedStage} complete`,actions);decorateResult(win,finishedStage);}
function finish(win){if(runResolved)return;runResolved=true;paused=true;cancelDrag();endBossIntro();const gems=win?rules.economy.gemsPerVictory:0;runReward={coins:earned,gems,doubled:false};saved.coins+=earned;saved.gems=(saved.gems||0)+gems;saved.freeUsed={};const finishedStage=stageNumber();if(win){saved.completedStages++;saved.chapter=saved.completedStages%rules.chapters.length;}save();resultDialog(win,finishedStage);}
function rewardConfetti(){return '<div class="victory-confetti" aria-hidden="true">'+Array.from({length:42},(_,i)=>`<i style="--i:${i};--x:${i*43%100}%;--h:${[42,120,180,285,335][i%5]}"></i>`).join('')+'</div>';}
function decorateResult(win,stage){const box=$('#production-dialog'),panel=box.querySelector('section');panel.classList.add('result-panel');if(win){panel.classList.add('victory-panel');panel.querySelector('h2').innerHTML='<svg class="victory-cup" viewBox="0 0 120 105" aria-hidden="true"><path d="M28 16H10V37Q10 57 39 57M92 16H110V37Q110 57 81 57" fill="none" stroke="#20261b" stroke-width="12"/><path d="M28 16H10V37Q10 57 39 57M92 16H110V37Q110 57 81 57" fill="none" stroke="#ffd84a" stroke-width="7"/><path d="M28 7H92L86 43Q82 66 65 71V86H84V98H36V86H55V71Q38 66 34 43Z" fill="#ffc72d" stroke="#23271c" stroke-width="5"/><path d="M36 15H84L80 27H39Z" fill="#fff2a3"/><path d="M59 31L64 41L76 43L67 51L69 62L59 57L49 62L51 51L43 43L55 41Z" fill="#fff2b0"/></svg><b>STAGE CLEAR!</b>';box.insertAdjacentHTML('beforeend',rewardConfetti());tone(660);setTimeout(()=>tone(880),140);setTimeout(()=>tone(1320),300);}panel.querySelector('p').innerHTML=`<small>STAGE ${stage} ${win?'COMPLETE':'REWARDS'}</small><div class="result-rewards"><div>${icon('coin')}<strong>+${(runReward?.coins||0).toLocaleString()}</strong></div>${runReward?.gems?`<div>${gemIcon()}<strong>+${runReward.gems}</strong></div>`:''}</div>`;const double=panel.querySelector('[data-action="0"]');if(double&&double.textContent==='CLAIM ×2')double.innerHTML=icon('video')+icon('coin')+'<span>CLAIM ×2</span>';}
function prepareRewardFlight(){if(!runReward)return;rewardFlight={...runReward,start:performance.now(),progress:0,particles:[]};}
function displayBalance(key){const value=saved[key]||0,hidden=rewardFlight?Math.round(rewardFlight[key]*(1-rewardFlight.progress)):0;return Math.max(0,value-hidden);}
function launchRewardFlight(){if(!rewardFlight)return;const layer=document.createElement('div');layer.id='reward-flight';layer.setAttribute('aria-hidden','true');frame.append(layer);if(reducedMotion())return;for(const kind of ['coins','gems']){if(!rewardFlight[kind])continue;for(let i=0;i<(kind==='coins'?22:10);i++){const node=document.createElement('span');node.className='flying-reward '+kind;node.innerHTML=kind==='coins'?icon('coin'):gemIcon();layer.append(node);rewardFlight.particles.push({node,kind,i,delay:i*.035+(kind==='gems'?.12:0),angle:i*2.399,radius:75+(i*37%100)});}}}
function tickRewardFlight(now){if(!rewardFlight)return;const elapsed=(now-rewardFlight.start)/1000,duration=reducedMotion()?.35:2.15;rewardFlight.progress=Math.min(1,Math.max(0,(elapsed-.45)/(duration-.45||.1)));if(reducedMotion())rewardFlight.progress=Math.min(1,elapsed/.35);const beat=Math.floor(rewardFlight.progress*16);if(beat>(rewardFlight.beat||0)){rewardFlight.beat=beat;tone(850+beat*22);}const rect=frame.getBoundingClientRect();for(const p of rewardFlight.particles){const t=Math.max(0,elapsed-p.delay),burst=Math.min(1,t/.35),fly=Math.max(0,Math.min(1,(t-.4)/1)),ease=fly*fly*(3-2*fly),cx=rect.width*.5,cy=rect.height*.48,bx=cx+Math.cos(p.angle)*p.radius*burst,by=cy+Math.sin(p.angle)*p.radius*burst,target=(p.kind==='coins'?$('.top-currency'):gemWallet).getBoundingClientRect(),tx=target.left-rect.left+target.width*.3,ty=target.top-rect.top+target.height*.5,x=bx+(tx-bx)*ease,y=by+(ty-by)*ease-Math.sin(fly*Math.PI)*70;p.node.style.transform=`translate3d(${x}px,${y}px,0) rotate(${p.i*23+fly*180}deg) scale(${1-.35*fly})`;p.node.style.opacity=t<=0||fly>=1?'0':'1';}if(elapsed>=duration){rewardFlight=null;$('#reward-flight')?.remove();$('.top-currency').classList.add('reward-arrived');gemWallet.classList.add('reward-arrived');setTimeout(()=>{$('.top-currency').classList.remove('reward-arrived');gemWallet.classList.remove('reward-arrived');},350);tone(1100);}}
function openPause(){if(sceneSplash||!$('#production-dialog').hidden)return;cancelDrag();paused=true;$('#pause-overlay').hidden=false;$('#pause-overlay section>span').textContent=scene==='battle'?'PAUSED':'SETTINGS';$('#pause-title').textContent=scene==='battle'?'TAKE A BREAK':'GARDEN SETTINGS';$('#pause-overlay section>p').textContent=scene==='battle'?'The battle is paused.':'Your progress is saved in this browser.';$('#pause-to-home').hidden=scene!=='battle';$('#resume-battle').focus();}
$('#battle-pause').onclick=openPause;$('#settings').onclick=openPause;
$('#resume-battle').onclick=()=>{$('#pause-overlay').hidden=true;paused=false;$('#battle-pause').focus();};
$('#pause-to-home').onclick=()=>{$('#pause-overlay').hidden=true;$('#return-home-overlay').hidden=false;$('#cancel-home').focus();};
$('#cancel-home').onclick=()=>{$('#return-home-overlay').hidden=true;$('#pause-overlay').hidden=false;$('#resume-battle').focus();};
$('#confirm-home').onclick=()=>{runResolved=true;earned=0;units=[];enemies=[];shots=[];saved.freeUsed={};save();paused=false;$('#return-home-overlay').hidden=true;showSceneSplash('home');};
$('#start').onclick=()=>{if(scene!=='home'||sceneSplash)return;showSceneSplash('battle',{resetBattle:true});};
$('#home-roster').onclick=()=>{if(!sceneSplash)setScene('plants');};$('#home-battle').onclick=()=>{if(!sceneSplash)setScene('home');};$('#skip-boss').onclick=endBossIntro;
document.querySelectorAll('[data-upgrade]').forEach(b=>b.onclick=()=>{if(scene!=='home'||sceneSplash)return;const key=b.dataset.upgrade,cost=costFor(saved,key);if(saved.coins>=cost){saved.coins-=cost;increaseStat(saved,key);save();syncHome();tone(660);}else if(!saved.freeUsed[key]){timedBonus('BONUS UPGRADE','Local bonus · Claim one free '+({health:'Castle Health',rate:'Sunlight Rate',income:'Income'})[key]+' upgrade.',()=>{saved.freeUsed[key]=true;increaseStat(saved,key);save();hideDialog();syncHome();},hideDialog)}});
const soundButton=document.createElement('button');soundButton.id='sound-toggle';soundButton.classList.add('asset-button');soundButton.setAttribute('role','switch');$('#pause-overlay section').append(soundButton);function soundLabel(){soundButton.innerHTML='<span class="sr-only">SOUND '+(saved.sound?'ON':'OFF')+'</span>';soundButton.setAttribute('aria-label','Sound '+(saved.sound?'on':'off'));soundButton.setAttribute('aria-checked',String(saved.sound));soundButton.style.setProperty('--button-art',`url("${saved.sound?popupArt.soundOn:popupArt.soundOff}")`);}soundButton.onclick=()=>{saved.sound=!saved.sound;save();soundLabel();};soundLabel();
window.addEventListener('keydown',e=>{if(e.key==='Escape'){if($('#recruit-celebration')){closeRecruit();return;}if(!$('#production-dialog').hidden)return;if(!$('#return-home-overlay').hidden){$('#cancel-home').click();return;}if(bossIntro){endBossIntro();return;}if(!$('#pause-overlay').hidden){$('#resume-battle').click();return;}openPause();}if(e.key==='Tab'){const box=[$('#recruit-celebration'),$('#production-dialog'),$('#return-home-overlay'),$('#pause-overlay')].find(n=>n&&!n.hidden);if(!box)return;const buttons=[...box.querySelectorAll('button:not(:disabled)')].filter(b=>!b.hidden),first=buttons[0],last=buttons.at(-1);if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
function updateUI(){canvas.dataset.zoom=zoom.toFixed(3);canvas.removeAttribute('title');const waveTotal=countForWave(saved,wave),track=$('.wave-track');track.setAttribute('role','progressbar');track.setAttribute('aria-label','Enemies defeated this wave');track.setAttribute('aria-valuemin','0');track.setAttribute('aria-valuemax',String(waveTotal));track.setAttribute('aria-valuenow',String(waveKilled));track.querySelector('i').style.width=(Math.min(waveTotal,waveKilled)/waveTotal*100)+'%';$('.wave-head').style.setProperty('--wave-progress',(waveProgress(waveKilled,waveTotal)*100)+'%');wavePointer.hidden=countdown>0;wavePointer.style.left=(3+waveProgress(waveKilled,waveTotal)*94)+'%';if(bonusReady){const b=$('#production-dialog [data-action="0"]'),remain=Math.max(0,Math.ceil((bonusReady-performance.now())/1000));if(b){b.disabled=remain>0;b.textContent=remain?'CONTINUE IN '+remain:'CLAIM';const close=$('#production-dialog .bonus-close');if(close)close.hidden=remain===0;}}$('#coins').textContent=money(scene==='battle'?earned:displayBalance('coins'));$('#gems').textContent=money(displayBalance('gems'));gemWallet.setAttribute('aria-label','Gems '+(saved.gems||0));$('#sun-count').textContent=Math.floor(sun);$('.wave-number').innerHTML=wave+' <small>/ '+chapter().waves+'</small>';$('#wave-countdown').textContent=scene==='battle'&&countdown>0?'Wave starts in '+Math.ceil(countdown):'';$('#production-fill').style.width=(sun>=999?100:sun%1*100)+'%';$('.sun-stock').style.setProperty('--sun-progress',(sun>=999?100:sun%1*100)+'%');$('.production-track').setAttribute('aria-valuenow',String(sun>=999?100:Math.floor(sun%1*100)));$('.sun-stock').setAttribute('aria-label','Sunlight '+Math.floor(sun)+' of 999');document.querySelectorAll('.troop-card').forEach(b=>{const enough=sun>=costs[+b.dataset.type];b.classList.toggle('unaffordable',!enough);b.setAttribute('aria-disabled',String(!enough));});$('#unit-inspector').hidden=true;$('#placement-tip').hidden=true;canvas.setAttribute('aria-label',scene==='battle'?`Stage ${stageNumber()}, wave ${wave} of ${chapter().waves}. Sunlight ${Math.floor(sun)}. Base health ${Math.ceil(baseHp)} of ${baseMaxHp}. Plants ${units.length}. Enemies ${enemies.length}. ${paused?'Paused.':''}`:`${scene}. Stage ${stageNumber()}. Coins ${saved.coins}.`);}

const tutorial=document.createElement('div');tutorial.id='merge-tutorial';tutorial.className='battle-only';tutorial.setAttribute('role','status');tutorial.innerHTML='<img alt=""><span></span>';frame.append(tutorial);const hintAtlas=await loadImage('../../../assets/cartoon-v5-tutorial-hand.png'),hintCanvas=document.createElement('canvas');hintCanvas.width=345;hintCanvas.height=255;hintCanvas.getContext('2d').drawImage(hintAtlas,143,600,345,255,0,0,345,255);tutorial.querySelector('img').src=hintCanvas.toDataURL();
function updateTutorial(){tutorial.hidden=scene!=='battle'||saved.tutorial||paused||!!bossIntro||!!sceneSplash;if(tutorial.hidden)return;const pair=units.some(u=>units.some(v=>u!==v&&u.type===v.type&&u.level===v.level&&u.level<10));tutorial.querySelector('span').textContent=!units.length?'Drag a plant onto a tile':pair?'Drag matching plants together':'Add one more matching plant';const anchor=units.length?visualPosition(units[0]):{x:600,y:410};tutorial.style.left=(50+(anchor.x-600)*zoom/W*100)+'%';tutorial.style.top=(units.length?Math.min(67,(center.y+(anchor.y-center.y)*zoom+45)/H*100):70)+'%';}
async function finishBoot(){const overlay=$('#boot-loading'),shown=+$('#boot-logo').dataset.shownAt||performance.now(),remaining=reducedMotion()?0:Math.max(0,1800+shown-performance.now());if(remaining)await new Promise(resolve=>setTimeout(resolve,remaining));document.body.classList.add('ready');overlay.classList.add('leaving');if(!reducedMotion())await new Promise(resolve=>setTimeout(resolve,200));overlay.hidden=true;last=performance.now();}
// Fixed simulation steps preserve combat while browser rendering is throttled.
function advanceElapsed(seconds){let remaining=Math.max(0,seconds);while(remaining>1e-7){const dt=Math.min(1/30,remaining);tickVisuals(dt);tickSceneSplash(dt);if(!paused&&!sceneSplash){if(bossIntro){bossIntro.elapsed+=dt;if(bossIntro.elapsed>=introDuration)endBossIntro();}update(dt*(bossIntro?.12:1));}remaining-=dt;if(paused||(!sceneSplash&&scene!=='battle')||runResolved){if(!paused)time+=remaining;break;}}}
function advanceFrame(now){if(now<=last)return;const elapsed=Math.max(0,(now-last)/1000);last=now;advanceElapsed(elapsed);}
function loop(now){advanceFrame(now);tickRewardFlight(now);updateTutorial();if(bossIntro)$('#boss-cinematic').style.setProperty('--intro-opacity',String(introWeight()));if(messageUntil&&now>messageUntil){$('#game-message').classList.remove('visible');messageUntil=0;}updateUI();render();requestAnimationFrame(loop);}
try{const clockWorker=new Worker(new URL('./background-clock.js?v=production-22',import.meta.url));clockWorker.onmessage=()=>{if(document.hidden)advanceFrame(performance.now());};}catch{setInterval(()=>{if(document.hidden)advanceFrame(performance.now());},250);}
$('.production-track').setAttribute('role','progressbar');$('.production-track').setAttribute('aria-label','Charging next sunlight');$('.production-track').setAttribute('aria-valuemin','0');$('.production-track').setAttribute('aria-valuemax','100');applyTheme();buildCards();setScene(new URLSearchParams(location.search).get('screen')==='plants'?'plants':'home');updateUI();render();requestAnimationFrame(loop);await finishBoot();





